#pragma once
// version.dll export forwarding. The exported stubs live in version_stubs.asm
// (generated by gen_proxy.py); they jump through sr2_proxy_table, which is
// filled lazily from the real System32 version.dll on first use.

#include <windows.h>

namespace sr2::proxy {

// Loads the real version.dll (full System32 path) if not yet loaded.
// Safe to call from any thread, but NOT from DllMain.
bool EnsureLoaded();

// Full path of the real DLL that was (or would be) loaded.
const wchar_t* RealDllPath();

// Win32 error from the last failed load, 0 if none.
DWORD LoadError();

// Number of generated stubs / how many were found in the real DLL.
unsigned StubCount();
unsigned MissingCount();

}  // namespace sr2::proxy
